//! `hex mcp` speaks MCP over stdio against synthetic fixture meetings.
#![cfg(target_os = "macos")]

use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::mpsc;
use std::time::Duration;

use serde_json::{Value, json};

#[test]
fn mcp_server_initializes_lists_tools_and_answers_calls_over_stdio() {
    let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/meetings");
    let support =
        std::env::temp_dir().join(format!("voice-control-mcp-support-{}", std::process::id()));
    let mut child = Command::new(env!("CARGO_BIN_EXE_voice-control"))
        .arg("mcp")
        .arg("--meetings-dir")
        .arg(&fixtures)
        .env("HEX_APPLICATION_SUPPORT_DIR", &support)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .unwrap();
    let mut stdin = child.stdin.take().unwrap();
    let stdout = child.stdout.take().unwrap();
    let (sender, receiver) = mpsc::channel();
    std::thread::spawn(move || {
        for line in BufReader::new(stdout).lines() {
            let Ok(line) = line else { break };
            if sender.send(line).is_err() {
                break;
            }
        }
    });
    let mut send = move |message: Value| {
        writeln!(stdin, "{message}").unwrap();
        stdin.flush().unwrap();
    };
    let receive = |id: u64| -> Value {
        loop {
            let line = receiver
                .recv_timeout(Duration::from_secs(20))
                .expect("MCP response");
            let message: Value = serde_json::from_str(&line)
                .unwrap_or_else(|error| panic!("stdout must carry only JSON-RPC: {error}: {line}"));
            if message["id"] == json!(id) {
                return message;
            }
        }
    };

    send(
        json!({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {
            "protocolVersion": "2025-06-18",
            "capabilities": {},
            "clientInfo": {"name": "hex-test", "version": "1"}
        }}),
    );
    let initialized = receive(1);
    assert_eq!(initialized["result"]["serverInfo"]["name"], "hex-meetings");
    assert!(initialized["result"]["capabilities"]["tools"].is_object());
    send(json!({"jsonrpc": "2.0", "method": "notifications/initialized"}));

    send(json!({"jsonrpc": "2.0", "id": 2, "method": "tools/list"}));
    let tools = receive(2);
    let tools = tools["result"]["tools"].as_array().unwrap();
    let mut names = tools
        .iter()
        .map(|tool| tool["name"].as_str().unwrap())
        .collect::<Vec<_>>();
    names.sort_unstable();
    assert_eq!(
        names,
        [
            "get_meeting_notes",
            "get_transcript",
            "list_meetings",
            "search_transcripts"
        ]
    );
    for tool in tools {
        assert_eq!(tool["annotations"]["readOnlyHint"], true, "{tool}");
        assert_eq!(tool["inputSchema"]["type"], "object", "{tool}");
    }
    let search = tools
        .iter()
        .find(|tool| tool["name"] == "search_transcripts")
        .unwrap();
    assert_eq!(search["inputSchema"]["required"], json!(["query"]));

    send(
        json!({"jsonrpc": "2.0", "id": 3, "method": "tools/call", "params": {
            "name": "search_transcripts",
            "arguments": {"query": "Dax", "limit": 3}
        }}),
    );
    let result = receive(3);
    let text = result["result"]["content"][0]["text"].as_str().unwrap();
    assert!(text.contains("1790000000000-1001"), "{text}");
    assert!(text.contains("**Dax**"), "{text}");

    send(
        json!({"jsonrpc": "2.0", "id": 4, "method": "tools/call", "params": {
            "name": "get_transcript",
            "arguments": {"meeting_id": "1790000000000-1001", "start": 20, "end": "0:30"}
        }}),
    );
    let result = receive(4);
    let text = result["result"]["content"][0]["text"].as_str().unwrap();
    assert!(text.contains("Showing 00:16–00:31"), "{text}");

    send(
        json!({"jsonrpc": "2.0", "id": 5, "method": "tools/call", "params": {
            "name": "get_meeting_notes",
            "arguments": {"meeting_id": "missing"}
        }}),
    );
    let result = receive(5);
    assert_eq!(result["result"]["isError"], true, "{result}");

    send(
        json!({"jsonrpc": "2.0", "id": 6, "method": "resources/read", "params": {
            "uri": "hex-meeting://1790000000000-1001"
        }}),
    );
    let result = receive(6);
    let markdown = result["result"]["contents"][0]["text"].as_str().unwrap();
    assert!(markdown.starts_with("# Weekly sync"), "{result}");

    drop(send);
    let status = child.wait().unwrap();
    assert!(status.success(), "{status}");
    assert!(
        !support.exists(),
        "hex mcp must not create Application Support state"
    );
}

import { Deferred, Effect, Fiber, Stream } from "effect"
import { watch } from "node:fs"
import { readFile, writeFile } from "node:fs/promises"
import { join } from "node:path"
import { describe, expect, it } from "vitest"
import * as Hex from "../src/effect.js"
import { options, processIsAlive, withTempDir } from "./support.js"

describe("Effect client", () => {
  it("creates a ready transcriber with scope-owned cleanup", async () => {
    let pid = 0
    const progress: string[] = []
    const result = await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const transcriber = yield* Hex.create({
        ...options(), model: "parakeet_v2", language: "en",
        onProgress: (event) => { progress.push(event.type) },
      })
      pid = transcriber.pid
      expect(transcriber.language).toBe("en")
      return yield* transcriber.transcribe(new Uint8Array([1, 2, 3]))
    })))
    expect(result.transcript).toBe("hello from hex")
    expect(progress).toEqual(["downloading", "verifying", "loading"])
    expect(processIsAlive(pid)).toBe(false)
  })

  it("interrupts model preparation and waits for helper cleanup", async () => {
    await withTempDir("hex-effect-ready-", async (directory) => {
      const pidPath = join(directory, "pid")
      let markStarted = () => {}
      const started = new Promise<void>((resolve) => { markStarted = resolve })
      await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
        const fiber = yield* Hex.create({
          ...options(), model: "parakeet_v2",
          env: { HEX_FAKE_PID_PATH: pidPath, HEX_FAKE_PREPARE_HANG: "1" },
          shutdownTimeoutMs: 100,
          onProgress: markStarted,
        }).pipe(Effect.forkScoped)
        yield* Effect.promise(() => started)
        yield* Fiber.interrupt(fiber)
        const pid = yield* Effect.promise(() => readFile(pidPath, "utf8"))
        expect(processIsAlive(Number(pid))).toBe(false)
      })))
    })
  })

  it("waits for interrupted inference to stop even while the owning scope stays open", async () => {
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const transcriber = yield* Hex.create({
        ...options(), model: "parakeet_v2", shutdownTimeoutMs: 100,
        env: { HEX_FAKE_TRANSCRIBE_HANG: "1" },
        fetch: async (url, init) => {
          const response = await fetch(url, init)
          if (String(url).includes("/transcriptions")) markStarted()
          return response
        },
      })
      const fiber = yield* transcriber.transcribe(new Uint8Array(4)).pipe(Effect.forkScoped)
      yield* Effect.promise(() => started)
      yield* Fiber.interrupt(fiber)
      expect(processIsAlive(transcriber.pid)).toBe(false)
    })))
  })

  it("cleans up pending startup interruption before returning to an open parent scope", async () => {
    await withTempDir("hex-effect-start-", async (directory) => {
      const pidPath = join(directory, "pid")
      const gate = join(directory, "handshake")
      const watcher = watch(directory)
      const started = new Promise<void>((resolve) => {
        watcher.on("change", (_event, file) => {
          if (file === "pid") resolve()
        })
      })
      try {
        await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
          const fiber = yield* Hex.create({
            ...options(), model: "parakeet_v2",
            env: { HEX_FAKE_PID_PATH: pidPath, HEX_FAKE_HANDSHAKE_GATE: gate },
          }).pipe(Effect.forkScoped)
          yield* Effect.promise(() => started)
          fiber.interruptUnsafe()
          yield* Effect.promise(() => writeFile(gate, "ready"))
          yield* Fiber.interrupt(fiber)
          const pid = yield* Effect.promise(() => readFile(pidPath, "utf8"))
          expect(processIsAlive(Number(pid))).toBe(false)
        })))
      } finally {
        watcher.close()
      }
    })
  })

  it.each([
    Hex.StartupError,
    Hex.ProtocolError,
    Hex.RequestError,
    Hex.ModelPreparationError,
    Hex.CancellationError,
  ])("preserves tagged error fields and yieldable failures for %s", async (ErrorClass) => {
    const cause = new Error("underlying failure")
    const error = new ErrorClass({ code: "test-failure", message: "operation failed", cause })
    expect(error).toBeInstanceOf(Error)
    expect(error._tag).toBe(`Hex.${ErrorClass.name}`)
    expect(error.message).toBe("operation failed")
    expect(error.cause).toBe(cause)
    const failure = await Effect.runPromise(Effect.gen(function* () {
      return yield* error
    }).pipe(Effect.flip))
    expect(failure).toBe(error)
  })

  it("scopes the helper and exposes Effect and Stream operations", async () => {
    let pid = 0
    const result = await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const host = yield* Hex.create(options())
      pid = host.pid
      const health = yield* host.client.health()
      const progress = yield* host.client.models.prepare("parakeet_v2", { language: "en" }).pipe(
        Stream.runCollect,
      )
      const transcript = yield* host.client.transcribe({
        audio: { data: new Uint8Array([1, 2, 3]), contentType: "audio/wav" },
        model: "parakeet_v2",
      })
      return { health, progress: Array.from(progress, (event) => event.type), transcript }
    })))

    expect(result).toEqual({
      health: { version: "test", apiVersion: "2" },
      progress: ["downloading", "verifying", "loading"],
      transcript: { transcript: "hello from hex", durationMs: 750 },
    })
    expect(processIsAlive(pid)).toBe(false)
  })

  it("provides the client as a scoped service layer", async () => {
    const health = await Effect.runPromise(
      Effect.gen(function* () {
        const hex = yield* Hex.Service
        return yield* hex.health()
      }).pipe(Effect.provide(Hex.layer(options()))),
    )

    expect(health.version).toBe("test")
  })

  it("interrupts an in-flight preparation when its stream scope closes", async () => {
    let pid = 0
    let requestSignal: AbortSignal | null | undefined
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const host = yield* Hex.create({
        ...options(),
        env: { HEX_FAKE_PREPARE_HANG: "1" },
        fetch: (url, init) => {
          if (String(url).includes("/prepare")) requestSignal = init?.signal
          return fetch(url, init)
        },
      })
      pid = host.pid
      const progress = yield* Deferred.make<void>()
      const fiber = yield* host.client.models.prepare("parakeet_v2").pipe(
        Stream.tap(() => Deferred.succeed(progress, undefined)),
        Stream.runDrain,
        Effect.forkScoped,
      )
      yield* Deferred.await(progress)
      yield* Fiber.interrupt(fiber)
      expect(requestSignal?.aborted).toBe(true)
      expect(processIsAlive(host.pid)).toBe(true)
      expect((yield* host.client.health()).apiVersion).toBe("2")
    })))

    expect(processIsAlive(pid)).toBe(false)
  })

  it("preserves typed preparation failures through the progress stream", async () => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const host = yield* Hex.create({ ...options(), env: { HEX_FAKE_PREPARE_ERROR: "1" } })
      const error = yield* host.client.models.prepare("parakeet_v2").pipe(Stream.runDrain, Effect.flip)
      expect(error).toMatchObject({
        _tag: "Hex.ModelPreparationError", code: "model-prepare-failed", remoteCode: "load-failed",
      })
      expect(processIsAlive(host.pid)).toBe(true)
    })))
  })
})

import { describe, expect, it } from "vitest"
import { prepareConfig } from "../src/host.js"
import { choice, digit, letter, union } from "../src/model.js"
import type { AtomicCaptureDescriptor } from "../src/model.js"

const registration = (capture: unknown) => prepareConfig({
  commands: {
    choose: { phrases: ["choose {value}"], captures: { value: capture }, run: async () => {} },
  },
}).registration.commands[0]?.captures?.value

describe("constructor and host capture agreement", () => {
  it("preserves distinct non-ASCII case while normalizing ASCII and spoken digits", () => {
    const members = [
      choice({ upper: ["Ä"], lower: ["ä"] }),
      choice({ count: [" TWO! "], home: ["HOME"] }),
    ] as const
    const constructed = union(...members)
    expect(registration({ type: "union", members })).toEqual(constructed)
    expect(registration(constructed)).toEqual(constructed)
    expect(constructed.members).toEqual([
      { type: "choice", choices: { upper: ["Ä"], lower: ["ä"] } },
      { type: "choice", choices: { count: ["2"], home: ["home"] } },
    ])
    expect(members[1].choices.count).toEqual([" TWO! "]) // no mutation of supplied descriptors
    expect(Object.isFrozen(constructed.members)).toBe(true)
  })

  const overlaps: readonly (readonly [AtomicCaptureDescriptor, AtomicCaptureDescriptor])[] = [
    [digit(), choice({ count: [" TWO! "] })],
    [letter(), choice({ first: ["ALPHA!"] })],
    [choice({ first: ["Home"] }), choice({ second: ["home!"] })],
    [choice({ first: ["! home"] }), choice({ second: ["home"] })],
  ]
  it.each(overlaps)("rejects the same normalized overlaps in constructors and raw descriptors", (first, second) => {
    expect(() => union(first, second)).toThrow("overlap")
    expect(() => registration({ type: "union", members: [first, second] })).toThrow("overlap")
  })

  it("shares nesting, flattening, member bounds, and invalid-leaf rejection", () => {
    // Exercise structural input from JavaScript, including unflattened nested unions.
    type RawUnion = { readonly type: "union"; readonly members: readonly (AtomicCaptureDescriptor | RawUnion)[] }
    let nested: RawUnion = { type: "union", members: [choice(["first"]), choice(["second"])] }
    for (let depth = 0; depth < 3; depth++) {
      nested = { type: "union", members: [choice([`level${depth}`]), nested] }
    }
    expect(registration(nested)).toEqual(Reflect.apply(union, undefined, nested.members))
    expect(() => Reflect.apply(union, undefined, [choice(["outer"]), nested])).toThrow("nesting")
    expect(() => registration({ type: "union", members: [choice(["outer"]), nested] })).toThrow("nesting")

    const excessive: [AtomicCaptureDescriptor, AtomicCaptureDescriptor, ...AtomicCaptureDescriptor[]] = [
      choice(["first"]), choice(["second"]), ...Array.from({ length: 15 }, (_, index) => choice([`extra${index}`])),
    ]
    expect(() => union(...excessive)).toThrow("at most 16")
    expect(() => registration({ type: "union", members: excessive })).toThrow("at most 16")
    expect(() => union(digit({ min: 4, max: 2 }), letter())).toThrow("digit range")
    expect(() => registration({ type: "union", members: [digit({ min: 4, max: 2 }), letter()] })).toThrow("digit range")
  })
})

import type { Effect, Scope } from "effect"
import * as Hex from "../src/index.js"
import * as EffectHex from "../src/effect.js"

// Compile-only consumer checks: never start a helper from a type assertion.
export function createTypes(
  low: Hex.CreateOptions,
  ready: Hex.TranscriberOptions,
  ambiguous: Omit<Hex.CreateOptions, "model"> & { model?: Hex.ModelId },
) {
  const host: Promise<Hex.HexHost> = Hex.create(low)
  const transcriber: Promise<Hex.Transcriber> = Hex.create(ready)
  const effectHost: Effect.Effect<EffectHex.Host, EffectHex.HexError, Scope.Scope> = EffectHex.create(low)
  const effectTranscriber: Effect.Effect<EffectHex.Transcriber, EffectHex.HexError, Scope.Scope> = EffectHex.create(ready)
  const invalid = { model: "fictional-model" }

  // @ts-expect-error A model-bound transcriber cannot masquerade as a low-level host.
  const widened: Hex.CreateOptions = ready
  // @ts-expect-error Optional models cannot determine which resource is returned.
  Hex.create(ambiguous)
  // @ts-expect-error Optional models cannot determine which resource is returned.
  EffectHex.create(ambiguous)
  // @ts-expect-error Invalid model variables must not fall back to the low-level overload.
  Hex.create(invalid)
  // @ts-expect-error Invalid model variables must not fall back to the low-level overload.
  EffectHex.create(invalid)
  // @ts-expect-error The existing service layer deliberately provides only the low-level client.
  EffectHex.layer(ready)

  return { host, transcriber, effectHost, effectTranscriber, widened }
}

import { describe, expect, it, vi } from "vitest"
import { writeFile } from "node:fs/promises"
import { join } from "node:path"
import { connect, create, HexError } from "../src/index.js"
import { makeClient } from "../src/client.js"
import { fixtureEndpoint, helper, options, processIsAlive, withTempDir } from "./support.js"

describe("Promise client", () => {
  it.each([
    ["{", "startup-failed", "Could not read the running HEX endpoint"],
    ["null", "invalid-handshake", "HEX discovery contained an invalid endpoint"],
    ["{}", "invalid-handshake", "HEX returned an invalid startup handshake"],
    [JSON.stringify({ port: "bad", token: "", apiVersion: "2", pid: 1 }), "invalid-handshake", "HEX returned an invalid service URL"],
  ])("preserves discovery errors for %s without making a request", async (contents, code, message) => {
    await withTempDir("hex-discovery-", async (directory) => {
      const discoveryPath = join(directory, "local-api.json")
      const fetch = vi.fn<typeof globalThis.fetch>()
      await writeFile(discoveryPath, contents)
      await expect(connect({ discoveryPath, fetch })).rejects.toMatchObject({ code, message })
      expect(fetch).not.toHaveBeenCalled()
    })
  })

  it("continues accepting a string discovery port and an empty token", async () => {
    await withTempDir("hex-discovery-", async (directory) => {
      const discoveryPath = join(directory, "local-api.json")
      const fetch = vi.fn<typeof globalThis.fetch>().mockResolvedValue(Response.json({ version: "test", apiVersion: "2" }))
      await writeFile(discoveryPath, JSON.stringify({ port: "1234", token: "", apiVersion: "2", pid: 1 }))
      await connect({ discoveryPath, fetch })
      expect(fetch).toHaveBeenCalledWith("http://127.0.0.1:1234/health", expect.any(Object))
    })
  })

  it("owns the helper and exercises the complete protocol", async () => {
    const host = await create(options())
    const progress: Array<string> = []

    expect(await host.client.health()).toEqual({ version: "test", apiVersion: "2" })
    expect(await host.client.capabilities()).toEqual({
      audioFormats: ["audio/wav"],
      partialTranscripts: false,
      serviceCapture: false,
    })
    expect(await host.client.models.list()).toMatchObject([{ id: "parakeet_v2", installed: true }])
    await host.client.models.prepare("parakeet_v2", {
      language: "en",
      onProgress: (event) => progress.push(event.type),
    })
    expect(progress).toEqual(["downloading", "verifying", "loading"])
    expect(await host.client.transcribe({
      audio: { data: new Uint8Array([1, 2, 3]), contentType: "audio/wav" },
      model: "parakeet_v2",
      language: "en",
    })).toEqual({ transcript: "hello from hex", durationMs: 750 })

    const pid = host.pid
    expect(processIsAlive(pid)).toBe(true)
