import { describe, expect, it, vi } from "vitest"
import { makeClient } from "../src/client.js"
import { consumeSse } from "../src/sse.js"
import { fixtureEndpoint } from "./support.js"

const response = (chunks: readonly Uint8Array[], cancel = () => {}, close = true) =>
  new Response(new ReadableStream<Uint8Array>({
    start(controller) {
      for (const chunk of chunks) controller.enqueue(chunk)
      if (close) controller.close()
    },
    cancel,
  }), { headers: { "content-type": "text/event-stream" } })

const encoded = (text: string) => new TextEncoder().encode(text)

describe("shared SSE framing", () => {
  it.each(["\n", "\r\n", "\r"])("decodes %j separators independently of byte chunks", async (separator) => {
    const bytes = encoded([
      ": comment", "event: ignored", "data: café", "data:  second", "",
      "data: tail",
    ].join(separator))
    for (const chunks of [[bytes], Array.from(bytes, (byte) => new Uint8Array([byte]))]) {
      const values: string[] = []
      await consumeSse(response(chunks), new AbortController().signal, "fixture", (data) => { values.push(data) })
      expect(values).toEqual(["café\n second", "tail"])
    }
  })

  it.each([
    ["line", `:${"x".repeat(64 * 1024)}\n\n`],
    ["event", `data: ${"x".repeat(32 * 1024)}\ndata: ${"x".repeat(32 * 1024)}\n\n`],
  ])("bounds an individual %s and cancels its body on failure", async (_kind, text) => {
    const cancel = vi.fn()
    await expect(consumeSse(
      response([encoded(text)], cancel, false), new AbortController().signal, "fixture", () => {},
    )).rejects.toMatchObject({ code: "invalid-response" })
    expect(cancel).toHaveBeenCalledTimes(1)
  })

  it("cancels on terminal completion without decoding trailing data", async () => {
    const cancel = vi.fn()
    const values: string[] = []
    await consumeSse(response([encoded("data: done\n\ndata: ignored\n\n")], cancel, false),
      new AbortController().signal, "fixture", (data) => {
        values.push(data)
        return true
      })
    expect(values).toEqual(["done"])
    expect(cancel).toHaveBeenCalledTimes(1)
  })

  it("preserves callback failure and releases the underlying body", async () => {
    const cancel = vi.fn()
    const failure = new Error("callback failed")
    await expect(consumeSse(response([encoded("data: event\n\n")], cancel, false),
      new AbortController().signal, "fixture", () => { throw failure }))
      .rejects.toBe(failure)
    expect(cancel).toHaveBeenCalledTimes(1)
  })
})

describe("SDK SSE consumers", () => {
  it("dispatches CR-only events and completes preparation without another byte or EOF", async () => {
    const cancel = vi.fn()
    const transport: typeof fetch = async () => response([
      encoded('data: {"type":"verifying"}\r\rdata: {"type":"ok"}\r\r'),
    ], cancel, false)
    const client = makeClient(fixtureEndpoint, transport, new AbortController().signal)
    const onProgress = vi.fn()
    await client.models.prepare("parakeet_v2", { onProgress })
    expect(onProgress).toHaveBeenCalledExactlyOnceWith({ type: "verifying" })
    expect(cancel).toHaveBeenCalledTimes(1)
  }, 1_000)

  it("accepts one large chunk of small progress and level events while bounding observations", async () => {
    const count = 3_000
    const progress = "data: {\"type\":\"verifying\"}\n\n".repeat(count) + "data: {\"type\":\"ok\"}\n\n"
    const levels = Array.from({ length: count }, (_, index) =>
      `data: ${JSON.stringify({ rmsDb: index, peakDb: index })}\n\n`).join("")
    const transport: typeof fetch = async (url) => {
      if (String(url).includes("/prepare")) return response([encoded(progress)])
      if (String(url).endsWith("/levels")) return response([encoded(levels)])
      if (String(url).endsWith("/dictations")) {
        return Response.json({ id: 1, ownerToken: "x".repeat(32), sampleRate: 16_000 })
      }
      return new Response(null, { status: 204 })
    }
    const client = makeClient(fixtureEndpoint, transport, new AbortController().signal)
    const onProgress = vi.fn()
    await client.models.prepare("parakeet_v2", { onProgress })
    expect(onProgress).toHaveBeenCalledTimes(count)
    const recording = await client.dictation.start({ source: "fixture" })
    try {
      const values = []
      for await (const level of recording.levels) values.push(level)
      expect(values.length).toBeLessThanOrEqual(33) // one waiting reader, then the 32-value sliding buffer
      expect(values.at(-1)).toEqual({ rmsDb: count - 1, peakDb: count - 1 })
    } finally {
      await recording.cancel()
    }
  })

  it.each(["throw", "abort"])("preserves %s from a progress callback ahead of buffered completion", async (operation) => {
    const cancel = vi.fn()
    const controller = new AbortController()
    const transport: typeof fetch = async () => response([
      encoded('data: {"type":"verifying"}\n\ndata: {"type":"ok"}\n\n'),
    ], cancel, false)
    const client = makeClient(fixtureEndpoint, transport, controller.signal)
    await expect(client.models.prepare("parakeet_v2", {
      onProgress: () => {
        if (operation === "abort") controller.abort("fixture cancellation")
        else throw new Error("fixture failure")
      },
    })).rejects.toMatchObject({ code: operation === "abort" ? "cancelled" : "request-failed" })
    expect(cancel).toHaveBeenCalledTimes(1)
  })
})

import { readFile } from "node:fs/promises"
import { join } from "node:path"
import { ChildProcess } from "node:child_process"
import { once } from "node:events"
import { describe, expect, it, vi } from "vitest"
import { create, type ModelProgress } from "../src/index.js"
import { options, processIsAlive, withTempDir } from "./support.js"

describe("ready transcriber", () => {
  it("prepares once and binds the model and language across recordings", async () => {
    const progress: ModelProgress[] = []
    const requests: string[] = []
    const input = {
      ...options(), model: "parakeet_v2" as const, language: "en",
      onProgress: (event: ModelProgress) => { progress.push(event) },
      fetch: async (url: string | URL | Request, init?: RequestInit) => {
        requests.push(String(url))
        return fetch(url, init)
      },
    }
    const creating = create(input)
    input.language = "fr"
    const transcriber = await creating
    try {
      expect(progress.map((event) => event.type)).toEqual(["downloading", "verifying", "loading"])
      expect(transcriber.model).toBe("parakeet_v2")
      expect(transcriber.language).toBe("en")
      for (const audio of [new Uint8Array([1, 2, 3]), new ArrayBuffer(4)]) {
        expect(await transcriber.transcribe(audio)).toEqual({ transcript: "hello from hex", durationMs: 750 })
      }
      expect(requests.filter((url) => url.includes("/prepare"))).toHaveLength(1)
      expect(requests.filter((url) => url.includes("/transcriptions")).map((url) => new URL(url).search))
        .toEqual(["?model=parakeet_v2&language=en", "?model=parakeet_v2&language=en"])
    } finally {
      await transcriber.close()
    }
    await transcriber.close()
    expect(processIsAlive(transcriber.pid)).toBe(false)
    await expect(transcriber.transcribe(new Uint8Array(4))).rejects.toMatchObject({ code: "service-exited" })
  })

  it.each(["error", "cancel", "callback"])("closes the helper before failed creation settles: %s", async (mode) => {
    await withTempDir("hex-ready-", async (directory) => {
      const pidPath = join(directory, "pid")
      const controller = new AbortController()
      await expect(create({
        ...options(), model: "parakeet_v2",
        env: { HEX_FAKE_PID_PATH: pidPath, HEX_FAKE_PREPARE_ERROR: "1" },
        signal: controller.signal,
        onProgress: () => {
          if (mode === "cancel") controller.abort()
          if (mode === "callback") throw new Error("UI callback failed")
        },
      })).rejects.toMatchObject({
        code: mode === "error" ? "model-prepare-failed" : mode === "cancel" ? "cancelled" : "request-failed",
      })
      expect(processIsAlive(Number(await readFile(pidPath, "utf8")))).toBe(false)
    })
  })

  it("does not close a ready transcriber for an already-aborted request", async () => {
    const transcriber = await create({ ...options(), model: "parakeet_v2" })
    try {
      await expect(transcriber.transcribe(new Uint8Array(4), { signal: AbortSignal.abort() }))
        .rejects.toMatchObject({ code: "cancelled" })
      expect(processIsAlive(transcriber.pid)).toBe(true)
      expect((await transcriber.transcribe(new Uint8Array(4))).transcript).toBe("hello from hex")
    } finally {
      await transcriber.close()
    }
  })

  it("does not let buffered success overtake cancellation", async () => {
    const controller = new AbortController()
    const transcriber = await create({
      ...options(), model: "parakeet_v2",
      fetch: async (url, init) => {
        const response = await fetch(url, init)
        if (String(url).includes("/transcriptions")) {
          const json = response.json.bind(response)
          response.json = async () => {
            const result: unknown = await json()
            controller.abort()
            return result
          }
        }
        return response
      },
    })
    try {
      await expect(transcriber.transcribe(new Uint8Array(4), { signal: controller.signal }))
        .rejects.toMatchObject({ code: "cancelled" })
      expect(processIsAlive(transcriber.pid)).toBe(false)
    } finally {
      await transcriber.close()
    }
  })

  it("reports failed startup cleanup instead of implying the child stopped", async () => {
    const children: ChildProcess[] = []
    const kill = vi.spyOn(ChildProcess.prototype, "kill").mockImplementation(function (this: ChildProcess) {
      children.push(this)
      throw new Error("Termination denied")
    })
    try {
      await expect(create({
        ...options(), model: "parakeet_v2", shutdownTimeoutMs: 1,
        env: { HEX_FAKE_MODE: "bad-handshake", HEX_FAKE_IGNORE_LEASE: "1" },
      })).rejects.toMatchObject({ code: "shutdown-failed" })
    } finally {
      kill.mockRestore()
      for (const child of children) {
        if (child.exitCode !== null || child.signalCode !== null) continue
        const exited = once(child, "exit")
        child.kill("SIGKILL")
        await exited
      }
    }
  })

  it.each(["abort", "close", "replaced-signal"])("waits for native ownership to end on %s", async (mode) => {
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    const controller = new AbortController()
    const transcriber = await create({
      ...options(), model: "parakeet_v2",
      env: { HEX_FAKE_TRANSCRIBE_HANG: "1" },
      fetch: async (url, init) => {
        const response = await fetch(url, init)
        if (String(url).includes("/transcriptions")) markStarted()
        return response
      },
    })
    try {
      const request = { signal: controller.signal }
      const result = expect(transcriber.transcribe(new Uint8Array(4), request))
        .rejects.toMatchObject({ code: mode === "close" ? "service-exited" : "cancelled" })
      await started
      if (mode === "replaced-signal") request.signal = new AbortController().signal
      if (mode === "close") void transcriber.close()
      else controller.abort()
      await result
      expect(processIsAlive(transcriber.pid)).toBe(false)
    } finally {
      await transcriber.close()
    }
  })

  it("keeps the helper alive after an ordinary request failure", async () => {
    const transcriber = await create({
      ...options(), model: "parakeet_v2", env: { HEX_FAKE_TRANSCRIBE_ERROR: "1" },
    })
    try {
      await expect(transcriber.transcribe(new Uint8Array(4)))
        .rejects.toMatchObject({ code: "request-failed", remoteCode: "model-not-ready" })
      expect(processIsAlive(transcriber.pid)).toBe(true)
    } finally {
      await transcriber.close()
    }
  })

  it("settles every pending request when one cancellation closes their helper", async () => {
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    let uploads = 0
    const controller = new AbortController()
    const transcriber = await create({
      ...options(), model: "parakeet_v2", env: { HEX_FAKE_TRANSCRIBE_HANG: "1" },
      fetch: async (url, init) => {
        const response = await fetch(url, init)
        if (String(url).includes("/transcriptions") && ++uploads === 2) markStarted()
        return response
      },
    })
    try {
      const first = expect(transcriber.transcribe(new Uint8Array(4), { signal: controller.signal }))
        .rejects.toMatchObject({ code: "cancelled" })
      const second = expect(transcriber.transcribe(new Uint8Array(4)))
        .rejects.toMatchObject({ code: "service-exited" })
      await started
      controller.abort()
      await Promise.all([first, second])
      expect(processIsAlive(transcriber.pid)).toBe(false)
    } finally {
      await transcriber.close()
    }
  })
})

import { describe, expect, it } from "vitest"
import { decodeEndpoint, decodeEndpointValue } from "../src/protocol.js"

const endpoint = {
  type: "ready",
  url: "http://127.0.0.1:1234",
  token: "",
  apiVersion: "2",
  pid: 1,
}

describe("endpoint decoding", () => {
  it("accepts the same endpoint from startup JSON and an already parsed value", () => {
    expect(decodeEndpoint(JSON.stringify(endpoint))).toEqual(endpoint)
    expect(decodeEndpointValue(endpoint)).toEqual(endpoint)
  })

  it("retains the startup JSON parse error and its cause", () => {
    expect(() => decodeEndpoint("{")).toThrowError(expect.objectContaining({
      code: "invalid-handshake",
      message: "HEX returned malformed startup JSON",
      cause: expect.any(SyntaxError),
    }))
  })

  it.each([
    [null, "invalid-handshake", "HEX returned an invalid startup handshake"],
    [{ ...endpoint, apiVersion: undefined }, "invalid-handshake", "HEX returned an invalid startup handshake"],
    [{ ...endpoint, apiVersion: "1", pid: 0 }, "incompatible-api", "HEX local API 1 is incompatible with client API 2; install a matching HEX app"],
    [{ ...endpoint, pid: 1.5 }, "invalid-handshake", "HEX returned an invalid startup handshake"],
    [{ ...endpoint, token: null }, "invalid-handshake", "HEX returned an invalid startup handshake"],
    [{ ...endpoint, url: "invalid" }, "invalid-handshake", "HEX returned an invalid service URL"],
    [{ ...endpoint, url: "http://user@127.0.0.1:1234" }, "invalid-handshake", "HEX service URL is not an authenticated loopback endpoint"],
  ])("preserves validation errors for %j", (value, code, message) => {
    for (const decode of [() => decodeEndpointValue(value), () => decodeEndpoint(JSON.stringify(value))]) {
      expect(decode).toThrowError(expect.objectContaining({ code, message }))
    }
  })
})

import { Effect } from "effect"
import { choice, defineHexConfig, digit, Hex, letter, press, text, union } from "../src/effect.js"
import type { Letter } from "../src/effect.js"

defineHexConfig({
  commands: {
    value: {
      phrases: ["effect value"],
      run: Effect.gen(function* () {
        const hex = yield* Hex
        yield* hex.typeText("value")
      }),
    },
    factory: {
      phrases: ["effect factory"],
      run: ({ context }) => Effect.gen(function* () {
        const hex = yield* Hex
        yield* hex.typeText(context.browserHost ?? "factory")
      }),
    },
    captures: {
      phrases: ["move {column} named {label}"],
      captures: {
        column: digit({ min: 1, max: 3 }),
        label: text(),
      },
      run: ({ captures }) => Effect.gen(function* () {
        const column: number = captures.column
        const label: string = captures.label
        const hex = yield* Hex
        yield* hex.typeText(`${column}:${label}`)
      }),
    },
    choice: {
      phrases: ["move {direction}"],
      captures: { direction: choice(["left", "right"] as const) },
      run: ({ captures }) => Effect.gen(function* () {
        const direction: "left" | "right" = captures.direction
        const hex = yield* Hex
        yield* hex.typeText(direction)
      }),
    },
    letter: {
      phrases: ["control {key}"],
      captures: { key: letter() },
      run: ({ captures }) => Effect.gen(function* () {
        const key: Letter = captures.key
        const hex = yield* Hex
        yield* hex.press({ key, modifiers: ["control"] })
      }),
    },
    union: {
      phrases: ["key {key}"],
      captures: { key: union(letter(), digit(), choice(["home", "escape"] as const)) },
      run: ({ captures }) => Effect.gen(function* () {
        const key: string | number = captures.key
        const hex = yield* Hex
        yield* hex.press(String(key))
      }),
    },
  },
})

defineHexConfig({
  commands: {
    invalidPromise: {
      phrases: ["invalid promise"],
      // @ts-expect-error Effect configs do not silently accept Promise handlers.
      run: async () => undefined,
    },
    invalidValue: {
      phrases: ["invalid value"],
      // @ts-expect-error Effect handlers must return an Effect.
      run: () => undefined,
    },
    invalidCapturedNativeAction: {
      phrases: ["control {number}"],
      captures: { number: digit() },
      // @ts-expect-error Typed captures require an Effect handler rather than a native run value.
      run: press("1"),
    },
  },
})

import { Deferred, Effect } from "effect"
import { describe, expect, it } from "vitest"
import { Hex } from "../src/effect.js"
import { choice, digit, letter, openUrl, text, union } from "../src/index.js"
import type { HandlerArguments, Letter } from "../src/index.js"
import { prepareConfig, runHost } from "../src/host.js"
import type { HostOutput } from "../src/protocol.js"

async function* messages(lines: readonly unknown[]): AsyncGenerator<string> {
  for (const line of lines) yield `${JSON.stringify(line)}\n`
}

const collectHost = async (config: unknown, lines: readonly unknown[]): Promise<HostOutput[]> => {
  const output: HostOutput[] = []
  await runHost({
    config,
    input: messages(lines),
    write: (frame) => { output.push(frame) },
  })
  return output
}

describe("command host", () => {
