    expect(prepared.registration).toEqual({
      type: "registration",
      protocolVersion: 2,
      dictation: {
        start: ["begin note"],
        stop: ["finish note"],
        send: ["send note"],
        cancel: ["discard note"],
      },
      transformations: [],
      commands: [
        {
          id: "native",
          phrases: ["open example"],
          execution: { type: "native", action: { type: "openUrl", url: "https://example.com" } },
        },
        {
          id: "handled",
          phrases: ["do work"],
          group: "Work",
